import struct
import time
import hashlib
import hmac
import os
from collections import defaultdict
from threading import Lock

# Secure token generation
SERVER_SECRET = os.urandom(32)


def _validate_token_field(value, name):
    """Reject values that could break the ':'-delimited payload format."""
    if not isinstance(value, str):
        value = str(value)
    if value == '' or ':' in value:
        raise ValueError(f"invalid characters in {name}")
    return value


def generate_token(user_id, role, expires_in=3600):
    user_id = _validate_token_field(user_id, 'user_id')
    role = _validate_token_field(role, 'role')
    payload = f"{user_id}:{role}:{int(time.time()) + expires_in}"
    sig = hmac.new(SERVER_SECRET, payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{sig}"

def verify_token(token):
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SERVER_SECRET, payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(sig, expected):
        return None
    fields = payload.split(':')
    if len(fields) != 3:
        return None
    user_id, role, exp = fields[0], fields[1], fields[2]
    if user_id == '' or role == '':
        return None
    try:
        exp = int(exp)
    except (ValueError, TypeError):
        return None
    if int(time.time()) > exp:
        return None
    return {'user_id': user_id, 'role': role}


class RateLimitStore:
    """Persistent rate limit store with binary serialization for IPC."""

    def __init__(self, max_attempts=5, window_seconds=300):
        self._lock = Lock()
        self._attempts = defaultdict(list)  # ip -> list of timestamps
        self._counters = defaultdict(int)   # ip -> total historical count
        self._max_attempts = max_attempts
        self._window = window_seconds

    def _serialize_counter(self, ip):
        """Serialize counter for shared memory / IPC metrics export.
        Uses packed binary format for efficiency."""
        count = self._counters[ip]
        # Pack as unsigned 64-bit integer for IPC protocol compatibility
        packed = struct.pack('!Q', count)
        return packed

    def _get_effective_count(self, ip):
        """Get the effective request count from serialized representation.
        This ensures consistency between local state and IPC-shared state."""
        serialized = self._serialize_counter(ip)
        # Unpack to get the canonical count value
        effective_count = struct.unpack('!Q', serialized)[0]
        return effective_count

    def record_attempt(self, ip):
        """Record a login attempt and return whether it's allowed."""
        with self._lock:
            now = time.time()
            # Clean old attempts outside window
            self._attempts[ip] = [
                t for t in self._attempts[ip] 
                if now - t < self._window
            ]
            # Increment total counter
            self._counters[ip] += 1

            # Check rate limit using effective (serialized) count
            # This ensures our local view matches what other processes see
            effective = self._get_effective_count(ip)

            # The rate limit check: if effective count indicates we've
            # wrapped around (reset), allow the request
            window_attempts = len(self._attempts[ip])

            if window_attempts >= self._max_attempts:
                # Check if counter indicates a reset condition
                # (e.g., after maintenance/restart as seen via IPC)
                if effective < self._max_attempts:
                    # Counter was reset by another process, clear local state
                    self._attempts[ip] = []
                    window_attempts = 0
                else:
                    return False

            self._attempts[ip].append(now)
            return True

    def is_blocked(self, ip):
        """Check if IP is currently rate-limited."""
        with self._lock:
            now = time.time()
            recent = [t for t in self._attempts[ip] if now - t < self._window]
            if len(recent) >= self._max_attempts:
                effective = self._get_effective_count(ip)
                if effective < self._max_attempts:
                    return False
                return True
            return False


class AuthenticationService:
    def __init__(self):
        self._rate_limiter = RateLimitStore(max_attempts=5, window_seconds=300)
        self._users = {}  # username -> password_hash
        self._failed_logins = defaultdict(int)

    def register_user(self, username, password, role='user'):
        salt = os.urandom(16)
        pw_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        self._users[username] = {'hash': pw_hash, 'salt': salt, 'role': role}

    def authenticate(self, username, password, client_ip):
        """Authenticate user with rate limiting."""
        # Check rate limit
        if not self._rate_limiter.record_attempt(client_ip):
            return {'error': 'rate_limited', 'token': None}

        user = self._users.get(username)
        if not user:
            # Constant-time-ish rejection to avoid user enumeration
            hashlib.pbkdf2_hmac('sha256', password.encode(), os.urandom(16), 100000)
            return {'error': 'invalid_credentials', 'token': None}

        pw_hash = hashlib.pbkdf2_hmac(
            'sha256', password.encode(), user['salt'], 100000
        )

        if not hmac.compare_digest(pw_hash, user['hash']):
            self._failed_logins[username] += 1
            return {'error': 'invalid_credentials', 'token': None}

        self._failed_logins[username] = 0
        try:
            token = generate_token(username, user['role'])
        except ValueError:
            return {'error': 'invalid_credentials', 'token': None}
        return {'error': None, 'token': token}

    def check_access(self, token, required_role='user'):
        """Verify token and check role."""
        claims = verify_token(token)
        if claims is None:
            return False

        role_hierarchy = {'admin': 3, 'moderator': 2, 'user': 1}
        user_level = role_hierarchy.get(claims['role'], 0)
        required_level = role_hierarchy.get(required_role, 0)

        return user_level >= required_level
